    func testDeviceRegistrationDoesNotCollideWithBuiltinCatalogue() async throws {
        let server = BackendNativeMCPServer()
        for entry in try BackendDeckCoreCatalogueLiterals.builtins() { try await server.registerTool(entry.tool) { _, _ in .failure("fixture handler not invoked") } }
        let definitions = try BackendDeckToolsMachinesDevices(service: BackendDeckToolsMachinesPortDevices()).definitions(environment: BackendDeckToolsMachinesPortEnvironment())
        for definition in definitions { try await server.registerTool(definition.spec, handler: definition.handler) }
        let tools = try await server.catalogue(); BackendDeckToolsMachinesPortEqual(tools.filter { $0.id.hasPrefix("devices.") }.count, 11)
    }
    func testDeviceIDRuleEqualsPagePattern() throws {
        let pattern = #"^(ios|android|avd):[A-Za-z0-9._:-]{1,120}$"#, page = try source("src/main/devices/ipc.ts"), native = try source("macos/TerminalDeckNative/Sources/TerminalDeckBackend/BackendDeckToolsMachinesDevices.swift")
        XCTAssertTrue(page.contains("const ID = /" + pattern + "/")); XCTAssertTrue(native.contains(pattern))
    }
    func testButtonsKeysModifiersAgreeWithDevicePage() throws {
        let page = try source("src/main/devices/ipc.ts")
        func values(_ name: String) throws -> [String] {
            let set = try NSRegularExpression(pattern: "const " + name + #" = new Set\(\[([^\]]*)\]"#)
            let found = try XCTUnwrap(set.firstMatch(in: page, range: NSRange(page.startIndex..<page.endIndex, in: page))), range = try XCTUnwrap(Range(found.range(at: 1), in: page)), body = String(page[range]), strings = try NSRegularExpression(pattern: "'([^']+)'")
            return strings.matches(in: body, range: NSRange(body.startIndex..<body.endIndex, in: body)).compactMap { Range($0.range(at: 1), in: body).map { String(body[$0]) } }.sorted()
        }
        BackendDeckToolsMachinesPortEqual(try values("BUTTONS"), BackendDeckToolsMachinesDeviceRules.buttons.sorted()); BackendDeckToolsMachinesPortEqual(try values("KEYS"), BackendDeckToolsMachinesDeviceRules.keys.sorted())
        let modifiers = try BackendDeckToolsMachinesPortSpec("devices.type").inputSchema["properties"]["modifiers"]["items"]["enum"].elements!.compactMap(\.string)
        BackendDeckToolsMachinesPortEqual(try values("MODIFIERS"), modifiers.sorted())
    }
