    func testPasswordFieldValueNeverLeavesTree() async throws { let fake = BackendDeckToolsMachinesPortDevices(); var password = DeviceNode(ref: "r", role: "AXTextField", label: "PIN", value: "4821", frame: .init(x: 0.1, y: 0.1, width: 0.5, height: 0.1)); password.valueRedacted = true; await fake.setRoot(password); let result = try await BackendDeckToolsMachinesPortDeviceCall(fake, "devices.tree", args()); XCTAssertFalse(result.structuredContent?.compact.contains("4821") == true); BackendDeckToolsMachinesPortEqual(result.structuredContent?["elements"].elements?.first?["secret"], .bool(true)) }
